mapper.select:
select count(type) as typeCount,ifNull(sum(duration_today),0) as durationToday
from course_learn
where user_id = #{userId}
and delete_flag = 0
and type = 0

    and learn_date = #{currentDate}

select count(type) as typeCount,ifNull(sum(duration_today),0) as durationToday
from course_learn
where user_id = #{userId}
and delete_flag = 0
and type = 1

    and DATE_FORMAT(alarm_start_time,'%Y-%m-%d') = #{currentDate}

select count(type) as typeCount,ifNull(sum(duration_time),0) as durationToday
from course_learn
where user_id = #{userId}
and delete_flag = 0
and type = 2

    and learn_date = #{currentDate}

SELECT COUNT(*) AS meditationCount, FLOOR(COALESCE(SUM(duration_time), 0)) AS meditationTime, COUNT(DISTINCT DATE_FORMAT(learn_date, '%Y-%m-%d')) AS meditationDay FROM course_learn WHERE delete_flag = 0 AND type = 0 AND user_id = #{userId}
and learn_date = #{currentDate}
and date_format(learn_date,'%Y-%m-%d')=date_format(#{currentDate},'%Y-%m-%d')
and date_format(learn_date,'%Y-%m')=date_format(#{currentDate},'%Y-%m')
and date_format(learn_date,'%Y')=date_format(#{currentDate},'%Y')

SELECT COUNT(*) AS sleepCount, FLOOR(COALESCE(SUM(COALESCE(duration_today, 0) + COALESCE(duration_tomorrow, 0)),0)) AS sleepTime, COUNT(DISTINCT DATE (alarm_start_time)) + COUNT(DISTINCT DATE (alarm_end_time)) - COUNT(DISTINCT CASE WHEN DATE (alarm_start_time) = DATE (alarm_end_time) THEN DATE (alarm_start_time) END) AS sleepDay FROM course_learn WHERE delete_flag = 0 AND type = 1 AND user_id = #{userId}
and learn_date = #{currentDate}
and date_format(learn_date,'%Y-%m-%d')=date_format(#{currentDate},'%Y-%m-%d')
and date_format(learn_date,'%Y-%m')=date_format(#{currentDate},'%Y-%m')
and date_format(learn_date,'%Y')=date_format(#{currentDate},'%Y')

SELECT COUNT(*) AS focusCount, FLOOR(COALESCE(SUM(duration_time), 0)) AS focusTime, COUNT(DISTINCT DATE_FORMAT(learn_date, '%Y-%m-%d')) AS focusDay FROM course_learn WHERE delete_flag = 0 AND type = 2 AND user_id = #{userId}
and learn_date = #{currentDate}
and date_format(learn_date,'%Y-%m-%d')=date_format(#{currentDate},'%Y-%m-%d')
and date_format(learn_date,'%Y-%m')=date_format(#{currentDate},'%Y-%m')
and date_format(learn_date,'%Y')=date_format(#{currentDate},'%Y')
